# 2xMI350X_EPYC_9655_pytorch_f16173d: 2 node(s) x 8 GPUs, per-GPU batch 1024, global batch 16384.
# Generated by the submission packaging tool from the launch parameters of the submitted runs.
# Load default settings
source $(dirname ${BASH_SOURCE[0]})/config_common.sh

export DGXNNODES=2                               # nodes
export NNODES=2                                  # nodes (read by run_and_time.sh and the trainer)
export DGXNGPU=8                                 # GPUs per node
export BATCH_SIZE=1024                           # per-GPU (per-rank) batch
export DENSE_LR=0.000002                         # post-warmup LR = 1e-6 x global batch / 8192
export SPARSE_LR=0.000002
export SKIP_EVAL_EPOCH_PCT=0.0303                # evaluation starts after this fraction of the epoch

# Multi-node RCCL settings of the submitted runs
export NCCL_IB_TIMEOUT=14
export NCCL_IGNORE_CPU_AFFINITY=1
export RCCL_MSCCL_ENABLE=0
export NCCL_NET_GDR_LEVEL=5
export NCCL_DMABUF_ENABLE=1
# ROCr IPC through the KFD ioctls (workaround for an intermittent RCCL IPC-import crash at
# multi-node start, ROCm/rocm-systems#8178). The ioctls exist only in the DKMS amdgpu driver,
# which publishes /sys/module/amdgpu/version; the submitted runs set it exactly then.
if [ -n "$(cat /sys/module/amdgpu/version 2>/dev/null)" ]; then
  export HSA_ENABLE_IPC_MODE_LEGACY=1
fi

# [SITE-SPECIFIC] RDMA fabric of the submitted runs (RoCEv2, 8 Broadcom bnxt_re HCAs per node).
# Change these to your HCA names (ibv_devices), RoCEv2 GID index (show_gids) and lossless
# traffic class; see docs/multi_node_config.md.
export NCCL_IB_HCA=bnxt_re0,bnxt_re1,bnxt_re2,bnxt_re3,bnxt_re4,bnxt_re5,bnxt_re6,bnxt_re7
export NCCL_IB_GID_INDEX=3
export NCCL_IB_TC=104
